from collections import namedtuple
import re
from .base import BaseScfcErrorFixer


class _MissingParam(namedtuple('_MissingParam', ['name', 'parent_name', 'dist_name'])):

    @staticmethod
    def parse_from(validation_message):
        """Parses matching validation messages"""
        name = _MissingParam._parse_name(validation_message)
        parent_name = _MissingParam._parse_parent_name(validation_message)
        dist_name = validation_message.dist_name
        return _MissingParam(name, parent_name, dist_name)

    @staticmethod
    def _parse_name(message):
        return message.text.replace('Incomplete configuration: ', '')

    @staticmethod
    def _parse_parent_name(message):
        if 'is missing from the' not in message.details:
            return None
        pattern = r"Mandatory parameter .* \(.*\) is missing from the (.*) \(.*\)\."
        match = re.match(pattern, message.details)
        if match is None:
            raise KeyError("can't match " + message.details)
        return match.group(1)

    def is_simple(self):
        """Returns True if this parameter is simple (has no parent list param) and False if it is complex."""
        return self.parent_name is None

    def is_complex(self):
        """Returns True if this parameter is complex (has a parent list param) and False if it is simple."""
        return not self.is_simple()


class MissingMandatoryParamFixer(BaseScfcErrorFixer):

    def can_fix(self, validation_message):
        """Returns true if this fixer can fix given SCFC validation error/warning, false otherwise"""
        return validation_message.is_error() and validation_message.details.startswith('Mandatory parameter ')

    def fix(self, validation_message, param_dictionary, scfc):
        """Fixes given SCFC validation error/warning in given SCFC xml using given parameter dictionary xml"""
        missing_param = _MissingParam.parse_from(validation_message)
        param_in_dictionary = self._find_param_in_dictionary(
            param_dictionary, missing_param.dist_name, missing_param.parent_name, missing_param.name)
        if missing_param.is_simple():
            managed_object = scfc.find_managed_object(missing_param.dist_name)
            self._add_param_to_managed_object(managed_object, param_in_dictionary)
        else:
            list_param = scfc.find_managed_object(missing_param.dist_name).find_list_param(missing_param.parent_name)
            self._add_param_to_list(list_param, param_in_dictionary)
